/**
 * Build a single-scope lamejs bundle for Node.js 25+.
 *
 * lamejs has broken module boundaries — implicit globals, circular deps.
 * This script concatenates all sources into ONE function scope. All vars
 * share the same scope, so all cross-references resolve naturally.
 *
 * Run: node scripts/build-lamejs-bundle.js
 */
const fs = require('fs');
const path = require('path');

const base = path.join(__dirname, '..', 'node_modules', 'lamejs', 'src', 'js');
const outFile = path.join(__dirname, '..', 'src', 'lib', 'vendor', 'lamejs-bundle.js');

const EXCLUDE = ['Tests.js'];
const allFiles = fs.readdirSync(base)
  .filter(f => f.endsWith('.js') && !EXCLUDE.includes(f))
  .map(f => f.replace('.js', ''));

// We need to topologically sort for initialization order.
// But since we'll be in one scope, all function declarations are hoisted.
// The main thing that matters is: `module.exports = X` assignments and
// code that runs at parse time (not inside functions).

// Load order: common first (defines utilities), then everything, index last.
// Within the "everything" set, order doesn't matter much because all
// define constructor functions which are hoisted.
const order = ['common'];
for (const name of allFiles) {
  if (name !== 'common' && name !== 'index') order.push(name);
}
order.push('index');

console.log('Files:', order.length);

let bundle = `/**
 * lamejs MP3 Encoder - bundled for Node.js 25+ compatibility.
 * Auto-generated by scripts/build-lamejs-bundle.js - do not edit.
 * All lamejs modules concatenated into a single scope.
 */
/* eslint-disable */
var __lamejs_exports = (function() {
`;

// Track what each file exports so we can map require() calls
// Most files do: module.exports = ClassName;
// common.js does: module.exports = { System, VbrMode, ... };
const exportMap = {};

for (const name of order) {
  const filePath = path.join(base, name + '.js');
  if (!fs.existsSync(filePath)) {
    console.log('  SKIP:', name);
    continue;
  }

  let src = fs.readFileSync(filePath, 'utf8');

  // Determine what this module exports
  const exportMatch = src.match(/module\.exports\s*=\s*(\w+)\s*;/);
  if (exportMatch) {
    exportMap[name] = exportMatch[1];
  }

  // Replace `var X = require('./X.js')` lines.
  // If the var name matches the exported name, comment out the whole line
  // (otherwise `var X = X` would shadow and become undefined).
  // If names differ, replace require() with the exported var name.
  src = src.replace(/var (\w+) = require\(['"]\.\/(\w+)\.js['"]\);/g, (match, varName, dep) => {
    const exported = exportMap[dep] || dep;
    if (varName === exported) {
      // Same name — just remove (the var is already in scope from the defining file)
      return `// [bundled] ${varName} in scope`;
    }
    // Different names (e.g. `var common = require('./common.js')` -> `var common = __common_exports`)
    return `var ${varName} = ${exported};`;
  });

  // For common.js: keep module.exports but capture it in a var
  // For other files: strip module.exports (the var is already in scope)
  if (name === 'common') {
    src = src.replace(/module\.exports\s*=\s*/, 'var __common_exports = ');
    // After common.js, the require('./common.js') in other files will resolve
    // to __common_exports. Update the exportMap.
    exportMap['common'] = '__common_exports';
  } else if (name === 'index') {
    // Keep module.exports for index.js but redirect to our return value
    src = src.replace(/module\.exports\.Mp3Encoder\s*=\s*Mp3Encoder;/,
      '// Mp3Encoder exposed via return');
    src = src.replace(/module\.exports\.WavHeader\s*=\s*WavHeader;/,
      '// WavHeader exposed via return');
  } else {
    src = src.replace(/module\.exports\s*=\s*\w+\s*;/g, '// [bundled] export removed');
  }

  bundle += `\n// ==== ${name}.js ====\n`;
  bundle += src;
  bundle += '\n';
}

bundle += `
return { Mp3Encoder: Mp3Encoder, WavHeader: WavHeader };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = __lamejs_exports;
}
`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, bundle);
console.log('Bundle written: ' + (fs.statSync(outFile).size / 1024).toFixed(0) + 'KB');
